export const documentationBase64ToBlob = (
  base64Value,
  mimeType = 'application/pdf'
) => {
  const binary = window.atob(base64Value);
  const bytes = new Uint8Array(binary.length);

  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }

  return new Blob([bytes], { type: mimeType });
};

export const openDocumentationPdf = (document) => {
  if (typeof window === 'undefined') return;

  try {
    if (document?.contentBase64) {
      const blob = documentationBase64ToBlob(document.contentBase64);
      const url = window.URL.createObjectURL(blob);
      const opened = window.open(url, '_blank', 'noopener,noreferrer');

      if (!opened) {
        window.location.href = url;
      }

      window.setTimeout(() => window.URL.revokeObjectURL(url), 5 * 60 * 1000);
      return;
    }

    if (document?.file) {
      window.open(document.file, '_blank', 'noopener,noreferrer');
    }
  } catch (error) {
    console.error('Impossible d’ouvrir le document PDF.', error);
    if (document?.file) {
      window.location.href = document.file;
    }
  }
};

export const downloadDocumentationPdf = (document) => {
  if (typeof window === 'undefined') return;

  try {
    const link = window.document.createElement('a');
    let objectUrl = null;

    if (document?.contentBase64) {
      const blob = documentationBase64ToBlob(document.contentBase64);
      objectUrl = window.URL.createObjectURL(blob);
      link.href = objectUrl;
    } else if (document?.file) {
      link.href = document.file;
    } else {
      return;
    }

    link.download =
      document.fileName ||
      String(document.file || '').split('/').pop() ||
      `${document.id || 'documentation'}.pdf`;
    link.style.display = 'none';

    window.document.body.appendChild(link);
    link.click();
    link.remove();

    if (objectUrl) {
      window.setTimeout(() => window.URL.revokeObjectURL(objectUrl), 10_000);
    }
  } catch (error) {
    console.error('Impossible de télécharger le document PDF.', error);
  }
};

